#!/usr/bin/env bash
# jetstack/cert-manager v1.20.2 - base variant: crds-enabled
# Path: pull the package, render this base variant locally, read the objects,
# then apply them with kubectl. No ConfigHub account is needed.
# Generated by scripts/generate-public-site.mjs from the committed package
# data for this base variant. Chart page: https://confighub.github.io/helm-expt/site/charts/jetstack-cert-manager-v1-20-2.html
set -euo pipefail

say() { printf '\n>> %s\n' "$*"; }

if ! command -v cub >/dev/null 2>&1; then
  printf 'cub is not installed. Install it with:\n  curl -fsSL https://hub.confighub.com/cub/install.sh | bash\nthen add ~/.confighub/bin to your PATH and re-run this script.\n' >&2
  exit 1
fi

if ! command -v kubectl >/dev/null 2>&1; then
  printf 'kubectl is required for the apply step.\n' >&2
  exit 1
fi

say "Pull the package and render the crds-enabled base variant into ./jetstack-cert-manager-v1-20-2-crds-enabled"
cub installer setup --pull oci://europe-west1-docker.pkg.dev/nth-fort-499605-q5/helm-expt/jetstack-cert-manager:v1.20.2 --base crds-enabled --work-dir ./jetstack-cert-manager-v1-20-2-crds-enabled --non-interactive --namespace cert-manager

say "Read what was rendered; nothing has touched the cluster yet"
ls ./jetstack-cert-manager-v1-20-2-crds-enabled/out/manifests

say "Ensure the cert-manager namespace exists"
kubectl create namespace cert-manager --dry-run=client -o yaml | kubectl apply -f -

if [ -d ./jetstack-cert-manager-v1-20-2-crds-enabled/out/secrets ]; then
  say "Apply rendered Secrets first"
  kubectl apply -f ./jetstack-cert-manager-v1-20-2-crds-enabled/out/secrets
fi

say "Apply the rendered objects"
kubectl apply -f ./jetstack-cert-manager-v1-20-2-crds-enabled/out/manifests

say "Done. The cluster received exactly the files in ./jetstack-cert-manager-v1-20-2-crds-enabled/out."
